def recues(mesures):
    return [m for m in mesures if m is not None]

def taux_perte(mesures):
    return round(100 * (len(mesures) - len(recues(mesures))) / len(mesures), 1)

def gigue(mesures):
    r = recues(mesures)
    if len(r) < 2:
        return 0
    return round(sum(abs(r[i + 1] - r[i]) for i in range(len(r) - 1)) / (len(r) - 1), 1)

def qualite(mesures):
    r = recues(mesures)
    if not r:
        return "coupée"
    moyenne = sum(r) / len(r)
    perte = taux_perte(mesures)
    if perte >= 10 or moyenne > 300:
        return "mauvaise"
    if perte > 0 or moyenne > 100 or gigue(mesures) > 30:
        return "moyenne"
    return "bonne"
